SELECT DISTINCT TRUNC(t1.tr_ymd) AS trYmd FROM sjt0fs t1 WHERE t1.corp_gr = #{corpGr}
AND t1.tr_cd = #{trCd}
AND t1.tr_cd IN (SELECT ta.tr_cd FROM szx1pt ta WHERE ta.obj_id = 'W_JA020C')
ORDER BY trYmd DESC

SELECT MAX(jm_cd)
  FROM sjm0jj
 WHERE koscom_cd = #{koscomCd}

   AND danc_gb   = #{dancGb}

{ CALL KFP.SR_JA021C(
